        frequency_dict = {}
        for num in lst:
            if num in frequency_dict:
                frequency_dict[num] += 1
            else:
                frequency_dict[num] = 1
        return frequency_dict

    def compare_frequency_with_integer(frequency_dict):
        for num, freq in frequency_dict.items():
            if freq >= num:
                return num
        return -1

    max_positive = find_max_positive_integer(lst)
    frequency_dict = calculate_frequency(lst)
    return compare_frequency_with_integer(frequency_dict)

